async function ensureChainLocal(chain: string) {
  try {
    await iptables(["-t", "nat", "-N", chain]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
  }
  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
  // issuance, migration remediation, backups, the Claude backfill — were hitting
  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
  // public IP is redirected; host-local :port traffic to anything else is
  // untouched, and the shared DNAT rules only match ports that actually forward.
  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
  if (publicIp) {
    try {
      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", chain]);
    } catch {
      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", chain]);
    }
  }
}

/**
 * The real, iptables-backed NatHost for the PRIMARY's own chain — the only
 * implementation production used before multi-node. The decision logic it is
 * handed to lives in lib/nat-rules.ts and is tested against an in-memory fake;
 * see the H5 incident note at the top of that file.
 */
function iptablesHost(chain: string): NatHost {
  return {
    ensureChain: () => ensureChainLocal(chain),
    listChain: async () => {
      const { stdout } = await exec("iptables", ["-t", "nat", "-S", chain]);
      return stdout;
    },
    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", chain, ...ruleSpec(r)]),
    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", chain, ...ruleSpec(r)]),
  };
}

/**
 * result — one intent, one chain, one host PER NODE, never merged.
 *
 * Before multi-node this pulled every server platform-wide into a single
 * intent and always applied it to the local host's chain — harmless with one
 * node, but wrong the moment a second one exists: a node-2 server's forward
 * would be planned correctly and then installed on the PRIMARY's own
 * iptables, pointing at a private IP (10.20.1.x) the primary has no route to
 * — a rule that can never work, sitting in the wrong place. Servers are now
 * grouped by their own `nodeId` (falling back to the primary for the rare
 * legacy row with none, matching worker/index.ts's `nodeFor()` fallback) and
 * each node's chain is reconciled independently against ITS OWN NatHost.
 *
 * Every node listed in the `Node` table is attempted — not just `enabled`
 * ones — because disabling a node only stops NEW placement there; a server
 * already running on a disabled/draining node still needs its forwarding
 * kept correct. A node whose agent isn't reachable (or has no token
 * configured yet) fails independently and is reported, never silently
 * skipped and never able to abort another node's sync — the same H5 lesson
 * ("one failure must not cascade") applied one level up.
 */
export async function syncPortForwards(): Promise<NatSyncResult[]> {
  const [nodes, servers] = await Promise.all([
    db.node.findMany(),
    db.server.findMany({
      where: {
        ipAddress: { not: null },
        sshPort: { not: null },
        status: { notIn: ["SUSPENDED", "DELETING"] },
      },
      include: { portForwards: true },
    }),
  ]);

  const primary = nodes.find((n) => n.isPrimary);
  const byNode = new Map<string, typeof servers>();
  for (const s of servers) {
    const nodeId = (s as { nodeId?: string | null }).nodeId ?? primary?.id;
    if (!nodeId) continue; // no node row at all yet (fresh DB) — nothing to reconcile against
    if (!byNode.has(nodeId)) byNode.set(nodeId, []);
    byNode.get(nodeId)!.push(s);
  }

  const results: NatSyncResult[] = [];
  const errors: string[] = [];

  for (const node of nodes) {
    const nodeServers = byNode.get(node.id) ?? [];
    const intent = planNatRules(nodeServers as unknown as ForwardSource[]);

    // Two data problems that used to be invisible because the old loop just
    // built whatever it was handed. Neither blocks this node's sync — the
    // ruleset installed is still verified end to end — but neither is
    // swallowed either.
    for (const c of intent.conflicts) {
      console.error(
        `[nat] ${node.name}: port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
          `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
      );
    }
    for (const r of intent.rejected) {
      console.error(`[nat] ${node.name}/${r.hostname}: no rule installed — ${r.reason}`);
    }

    try {
      const result = await reconcileNatChain(natHostFor(node, node.natChain), node.natChain, intent);
      if (result.unparsed.length) {
        console.warn(
          `[nat] ${node.name}/${node.natChain} contains ${result.unparsed.length} rule(s) this engine did ` +
            `not write and will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
        );
      }
      console.log(
        `[nat] ${node.name}/${node.natChain} verified: ${result.verified} rule(s) present ` +
          `(+${result.added} / -${result.deleted})`
      );
      results.push(result);
    } catch (e: any) {
      // Collected, not thrown immediately — one node's failure (agent
      // unreachable, no token configured, a genuinely broken ruleset) must
      // never prevent every OTHER node's sync from being attempted.
      const msg = `${node.name}/${node.natChain}: ${String(e?.message ?? e)}`;
      console.error(`[nat] sync FAILED for ${msg}`);
      errors.push(msg);
    }
  }

  if (errors.length) {
    throw new Error(`NAT sync failed for ${errors.length} node(s): ${errors.join(" | ")}`);
  }
  return results;
}

/**
 * For callers that must not be re-queued by a sync failure (server DELETE runs
 * this after the row is gone, so a throw dies on "Server not found" on retry and
 * the sync is never re-attempted — H5's aggravating factor).
 *
 * It still never claims success: the failure is logged in full and returned, so
 * the caller can surface it. What it will not do is convert a networking problem
 * into a stuck job that hides it.
 */
export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
  try {
    await syncPortForwards();
    return null;
  } catch (e: any) {
    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
    return e instanceof Error ? e : new Error(String(e));
  }
}
