import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { logError } from "../lib/log";
import { upsertMinecraftSubdomainDns, deleteMinecraftSubdomainDns } from "../lib/game-subdomain-dns";
import { gameFamilyForServer } from "./provision-health";
import { joinPortFor, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "../lib/games";

export type DnsTargetInput = {
  status: string;
  dedicatedIp: { address: string } | null;
  portForwards: { guestPort: number; publicPort: number; protocol: string }[];
  nodePublicIp: string | null | undefined;
  publicIpEnv: string | undefined;
  gamePort: number;
  gameProtocol: "tcp" | "udp";
};

/**
 * Pure resolution of "what ip:port should this server's subdomain point at
 * right now" — no I/O, fully unit-testable. Extracted out of syncGameServerDns
 * so the branching (dedicated vs. NAT-with-forward vs. NAT-without-forward vs.
 * suspended/deleting) can be tested directly.
 *
 * Matches on BOTH guestPort and protocol, not guestPort alone. Several
 * families (cs2/tf2/l4d2/gmod/sdtd — see GAME_JOIN_PORT_OVERRIDE in
 * lib/games.ts) bind the identical port NUMBER for two different services —
 * RCON on tcp, the actual game on udp — so a server can legitimately hold two
 * PortForward rows with the same guestPort and different protocol. Matching
 * on guestPort alone would non-deterministically resolve to whichever forward
 * happens to come first, sometimes handing out the RCON port as the "connect"
 * address — the exact class of bug already found and fixed for the dashboard's
 * raw-IP display 2026-09-06/07 (see joinPortFor's own doc comment). The
 * caller MUST pass the join port+protocol (via `joinPortFor`), not the raw
 * GAME_PORT/health-check port, for the same reason.
 */
export function resolveGameServerDnsTarget(input: DnsTargetInput): { ip: string; port: number } | null {
  if (input.status === "SUSPENDED" || input.status === "DELETING") return null;
  if (input.dedicatedIp) return { ip: input.dedicatedIp.address, port: input.gamePort };
  const forward = input.portForwards.find((f) => f.guestPort === input.gamePort && f.protocol === input.gameProtocol);
  const ip = input.nodePublicIp ?? input.publicIpEnv;
  return forward && ip ? { ip, port: forward.publicPort } : null;
}

/**
 * Single idempotent choke point for keeping a paid Minecraft server's DNS
 * (`<subdomain>.play.nxeon.cloud`, see lib/game-subdomain-dns.ts) in sync with
 * its actual reachable ip:port. Called from every place that can change that
 * ip:port: provision() (dedicated-IP servers only — see below), addPortForward/
 * deletePortForward (NAT servers), and suspend()/unsuspend().
 *
 * Never throws — a DNS hiccup must not fail provisioning, a port-forward save,
 * or a suspend/unsuspend cycle. Callers fire-and-forget via the SYNC_GAME_DNS
 * job (see worker/index.ts) rather than awaiting this inline.
 */
/**
 * Pure: which families get a managed subdomain, and whether it includes an
 * SRV record. Java gets the full A+SRV pair (no port to remember); Bedrock
 * and everything in `HOSTNAME_CONNECT_FAMILIES` (lib/games.ts — the single
 * source of truth shared with checkout/dashboard, so the family list can't
 * drift between call sites) get an A record only — a friendly hostname is
 * the most a subdomain can offer there (see game-subdomain-dns.ts). Every
 * other family either rejects hostnames outright (rust, palworld,
 * spaceengineers, sandstorm, arkasa — confirmed, not assumed) or has no
 * meaningful direct-connect flow at all (server browser/matchmaking only),
 * or is simply unverified. Extracted for the same reason
 * `resolveGameServerDnsTarget` was: fully unit-testable without touching
 * `syncGameServerDns`'s DB/HTTP I/O.
 */
export function dnsSupportForFamily(family: string | null): { managed: false } | { managed: true; includeSrv: boolean } {
  if (family === "minecraft") return { managed: true, includeSrv: true };
  if (family === "bedrock" || (family && HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily))) return { managed: true, includeSrv: false };
  return { managed: false };
}

export async function syncGameServerDns(serverId: string): Promise<void> {
  if (SANDBOX) return;
  try {
    const server = await db.server.findUnique({
      where: { id: serverId },
      include: {
        osTemplate: { select: { family: true } },
        gamePlan: { select: { gameFamily: true } },
        node: { select: { publicIp: true } },
        dedicatedIp: { select: { address: true } },
        portForwards: true,
      },
    });
    if (!server || !server.subdomain) return;

    const familyLike = server as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null };
    const family = gameFamilyForServer(familyLike);
    const support = dnsSupportForFamily(family);
    if (!support.managed) return;
    const includeSrv = support.includeSrv;
    // The JOIN port, not the RCON/health-check GAME_PORT — see this file's own
    // resolveGameServerDnsTarget doc comment for why that distinction matters.
    const join = joinPortFor(family as GameFamily);

    const target = resolveGameServerDnsTarget({
      status: server.status,
      dedicatedIp: server.dedicatedIp,
      portForwards: server.portForwards,
      nodePublicIp: server.node?.publicIp,
      publicIpEnv: process.env.PUBLIC_IP,
      gamePort: join.port,
      gameProtocol: join.protocol,
    });

    if (target) {
      await upsertMinecraftSubdomainDns({ subdomain: server.subdomain, ip: target.ip, port: target.port, includeSrv });
    } else {
      await deleteMinecraftSubdomainDns(server.subdomain);
    }
  } catch (e) {
    logError("game-subdomain-sync", e, { serverId });
  }
}
