model ServerArchive {
  id              String    @id @default(cuid())
  originalId      String    @unique
  hostname        String
  userId          String?
  userEmail       String
  isGameServer    Boolean   @default(false)
  /// The raw family slug ("minecraft", "palworld", ...) when isGameServer —
  /// NOT the same as serviceName below, which is the human plan name and
  /// can't be used to look up cover art. Null for a VPS.
  gameFamily      String?
  serviceName     String
  nodeName        String?
  region          String?
  vmid            Int?
  totalSpentCents Int       @default(0)
  provisionedAt   DateTime
  expiresAt       DateTime?
  deletedAt       DateTime  @default(now())
  reason          String

