  ok: true;
  hostname: string;
  ip: string;
  zone: string;
  action: "created" | "updated";
  /** True when the record was faked because we're running in sandbox mode. */
  simulated: boolean;
};
export type PointDnsResult = PointDnsOk | { ok: false; error: string };
