/// An Nxeon-operated, free, PUBLIC SHARED game server (e.g. the community
/// Valheim world). Admin-managed (/admin/free-servers) and additive: no
/// customer owns it, it has no Server/billing row, and nothing in the platform
/// reads this table until an admin creates a row and sets status LIVE — so the
/// feature is inert until the VM exists. The live online state and player
/// count are NEVER stored here: they come from a real Steam A2S query at read
/// time (lib/free-public-server.ts) and are simply absent when it can't answer.
model FreePublicServer {
  id             String   @id @default(cuid())
  /// URL/slug key, e.g. "valheim". Unique so each game has at most one row per slug.
  slug           String   @unique
  /// lib/games.ts GameFamily key ("valheim").
  game           String
  name           String
  tagline        String?
  /// PLANNED (not shown anywhere) | LIVE | MAINTENANCE (shown, flagged) | RETIRED (not shown).
  status         String   @default("PLANNED")
  /// Public connect host (a DNS name, never a raw IP) and the UDP game port.
  host           String
  port           Int
  /// Port the Steam A2S query is sent to. Valheim answers on game port + 1.
  queryPort      Int
  /// lib/node-regions.ts region code the box lives in, e.g. "bhs1".
  region         String?
  maxPlayers     Int      @default(10)
  /// OPEN (no password to publish) | PUBLISHED (a rotating password shown on
  /// the page; passwordHint holds the CURRENT value, which is not a secret).
  passwordPolicy String   @default("PUBLISHED")
  passwordHint   String?
  /// Cadence the published password is rotated, shown as plain text ("weekly").
  rotation       String?
  /// Wipe/reset policy shown to players.
  wipePolicy     String?
  /// Internal ops notes (never rendered publicly).
  notes          String?
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt
  samples        FreePublicServerSample[]

  @@index([status])
}

