    select: { id: true, hostname: true, nodeId: true, status: true, extraDiskGB: true, plan: { select: { ramMB: true, diskGB: true } }, gamePlan: { select: { ramMB: true, diskGB: true } }, dedicatedIp
  });
  const primaryId = nodes.find((n) => n.isPrimary)?.id;
  const ram = (s: (typeof servers)[number]) => s.gamePlan?.ramMB ?? s.plan.ramMB;
  const committed = new Map<string, number>();
  for (const s of servers) {
    const nid = s.nodeId ?? primaryId;
    if (nid) committed.set(nid, (committed.get(nid) ?? 0) + ram(s));
  }
  const plan = planDrain({
    source: { id: source.id, name: source.name, region: source.region, capacityRamMB: source.capacityRamMB, committedRamMB: committed.get(source.id) ?? 0, enabled: source.enabled, acceptsProvisions: s
    nodes: nodes.map((n) => ({ id: n.id, name: n.name, region: n.region, capacityRamMB: n.capacityRamMB, committedRamMB: committed.get(n.id) ?? 0, enabled: n.enabled, acceptsProvisions: n.acceptsProvi
    servers: servers
      .filter((s) => (s.nodeId ?? primaryId) === source.id)
